<?php
require __DIR__.'/includes/bootstrap.php';requireLogin();
if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?')->execute([currentUser()['user_id']]);redirect('notifications.php');}
$q=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC,notification_id DESC LIMIT 100');$q->execute([currentUser()['user_id']]);$updates=$q->fetchAll();$pageTitle='Your updates';require __DIR__.'/includes/header.php';?>
<div class="page-head"><div><p class="eyebrow">STAY IN THE LOOP</p><h1>Your updates.</h1></div><form method="post"><?=csrfField()?><button class="secondary">Mark all as read</button></form></div><ul class="notification-list"><?php foreach($updates as $u):?><li class="<?=$u['is_read']?'':'unread'?>"><?=e($u['message'])?><time datetime="<?=e($u['created_at'])?>"><?=e($u['created_at'])?></time><?php if($u['event_id']):?><a class="text-link" href="event.php?id=<?=(int)$u['event_id']?>">View event →</a><?php endif;?></li><?php endforeach;?></ul><?php if(!$updates):?><div class="empty-state"><span>◎</span><h3>You're all caught up.</h3><p>Booking and event updates will appear here.</p></div><?php endif;require __DIR__.'/includes/footer.php';?>
